  fun writeRuntimeEvent(arena: Arena, value: RuntimeEvent): MemorySegment {
    val result = mln_runtime_event.allocate(arena)
    mln_runtime_event.type(result, value.type.rawValue.toInt())
    mln_runtime_event.source_type(result, value.sourceType.rawValue.toInt())
    mln_runtime_event.source(result, value.source.toLong())
    mln_runtime_event.code(result, value.code)
    when (val variant = value.payload) {
      is RuntimeEventPayload.RenderFrame -> {
        mln_runtime_event.payload_type(
          result,
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_RENDER_FRAME(),
        )
        mln_runtime_event_payload
          .render_frame(mln_runtime_event.payload(result))
          .copyFrom(GeneratedValues.writeRuntimeEventRenderFrame(arena, variant.value))
      }
      is RuntimeEventPayload.RenderMap -> {
        mln_runtime_event.payload_type(
          result,
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_RENDER_MAP(),
        )
        mln_runtime_event_payload
          .render_map(mln_runtime_event.payload(result))
          .copyFrom(GeneratedValues.writeRuntimeEventRenderMap(arena, variant.value))
      }
      is RuntimeEventPayload.TileAction -> {
        mln_runtime_event.payload_type(
          result,
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_TILE_ACTION(),
        )
        mln_runtime_event_payload
          .tile_action(mln_runtime_event.payload(result))
          .copyFrom(GeneratedValues.writeRuntimeEventTileAction(arena, variant.value))
      }
      is RuntimeEventPayload.OfflineRegionStatus -> {
        mln_runtime_event.payload_type(
          result,
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_STATUS(),
        )
        mln_runtime_event_payload
          .offline_region_status(mln_runtime_event.payload(result))
          .copyFrom(GeneratedValues.writeRuntimeEventOfflineRegionStatus(arena, variant.value))
      }
      is RuntimeEventPayload.OfflineRegionResponseError -> {
        mln_runtime_event.payload_type(
          result,
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_RESPONSE_ERROR(),
        )
        mln_runtime_event_payload
          .offline_region_response_error(mln_runtime_event.payload(result))
          .copyFrom(
            GeneratedValues.writeRuntimeEventOfflineRegionResponseError(arena, variant.value)
          )
      }
      is RuntimeEventPayload.OfflineRegionTileCountLimit -> {
        mln_runtime_event.payload_type(
          result,
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_TILE_COUNT_LIMIT(),
        )
        mln_runtime_event_payload
          .offline_region_tile_count_limit(mln_runtime_event.payload(result))
          .copyFrom(
            GeneratedValues.writeRuntimeEventOfflineRegionTileCountLimit(arena, variant.value)
          )
      }
      is RuntimeEventPayload.CameraTransitionFinished -> {
        mln_runtime_event.payload_type(
          result,
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_CAMERA_TRANSITION_FINISHED(),
        )
        mln_runtime_event_payload
          .camera_transition_finished(mln_runtime_event.payload(result))
          .copyFrom(GeneratedValues.writeRuntimeEventCameraTransitionFinished(arena, variant.value))
      }
      RuntimeEventPayload.None -> {
        mln_runtime_event.payload_type(result, MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_NONE())
      }
      is RuntimeEventPayload.Unknown ->
        throw IllegalArgumentException("unknown native union variants cannot be submitted")
    }
    return result
  }

  fun readRuntimeEvent(source: MemorySegment, message: String = ""): RuntimeEvent =
    RuntimeEvent(
      type = RuntimeEventType(mln_runtime_event.type(source).toUInt()),
      sourceType = RuntimeEventSourceType(mln_runtime_event.source_type(source).toUInt()),
      source = mln_runtime_event.source(source).toULong(),
      code = mln_runtime_event.code(source),
      payload =
        when (mln_runtime_event.payload_type(source)) {
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_RENDER_FRAME() ->
            RuntimeEventPayload.RenderFrame(
              GeneratedValues.readRuntimeEventRenderFrame(
                mln_runtime_event_payload.render_frame(mln_runtime_event.payload(source))
              )
            )
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_RENDER_MAP() ->
            RuntimeEventPayload.RenderMap(
              GeneratedValues.readRuntimeEventRenderMap(
                mln_runtime_event_payload.render_map(mln_runtime_event.payload(source))
              )
            )
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_TILE_ACTION() ->
            RuntimeEventPayload.TileAction(
              GeneratedValues.readRuntimeEventTileAction(
                mln_runtime_event_payload.tile_action(mln_runtime_event.payload(source))
              )
            )
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_STATUS() ->
            RuntimeEventPayload.OfflineRegionStatus(
              GeneratedValues.readRuntimeEventOfflineRegionStatus(
                mln_runtime_event_payload.offline_region_status(mln_runtime_event.payload(source))
              )
            )
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_RESPONSE_ERROR() ->
            RuntimeEventPayload.OfflineRegionResponseError(
              GeneratedValues.readRuntimeEventOfflineRegionResponseError(
                mln_runtime_event_payload.offline_region_response_error(
                  mln_runtime_event.payload(source)
                )
              )
            )
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_TILE_COUNT_LIMIT() ->
            RuntimeEventPayload.OfflineRegionTileCountLimit(
              GeneratedValues.readRuntimeEventOfflineRegionTileCountLimit(
                mln_runtime_event_payload.offline_region_tile_count_limit(
                  mln_runtime_event.payload(source)
                )
              )
            )
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_CAMERA_TRANSITION_FINISHED() ->
            RuntimeEventPayload.CameraTransitionFinished(
              GeneratedValues.readRuntimeEventCameraTransitionFinished(
                mln_runtime_event_payload.camera_transition_finished(
                  mln_runtime_event.payload(source)
                )
              )
            )
          MapLibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_NONE() -> RuntimeEventPayload.None
          else ->
            RuntimeEventPayload.Unknown(
              mln_runtime_event.payload_type(source).toUInt(),
              mln_runtime_event.payload(source).toArray(ValueLayout.JAVA_BYTE),
            )
        },
      message = message,
    )

  fun writeRuntimeEventBatchView(arena: Arena, value: RuntimeEventBatchView): MemorySegment {
    val result = mln_runtime_event_batch_view.allocate(arena)
    mln_runtime_event_batch_view.size(result, mln_runtime_event_batch_view.sizeof().toInt())
    mln_runtime_event_batch_view.events(
      result,
      GeneratedValues.writeRuntimeEventArray(arena, value.events),
