    mln_runtime_event_batch_view.event_count(result, value.events.size.toLong())
    return result
  }

  fun readRuntimeEventBatchView(source: MemorySegment): RuntimeEventBatchView =
    RuntimeEventBatchView(
      events =
        run {
          val count = (mln_runtime_event_batch_view.event_count(source)).toLong()
          val stride = (mln_runtime_event_batch_view.event_size(source)).toLong()
          require(count in 0..Int.MAX_VALUE.toLong())
          require(stride >= mln_runtime_event.sizeof())
          val dataSize = (mln_runtime_event_batch_view.messages_size(source)).toLong()
          List(count.toInt()) { index ->
            val item =
              mln_runtime_event_batch_view
                .events(source)
                .reinterpret(count * stride)
                .asSlice(index.toLong() * stride, mln_runtime_event.sizeof())
            val offset = (mln_runtime_event.message_offset(item)).toLong()
            val length = (mln_runtime_event.message_size(item)).toLong()
            require(offset >= 0 && length >= 0 && offset <= dataSize && length <= dataSize - offset)
            GeneratedValues.readRuntimeEvent(
              item,
              GeneratedValues.readRawBytes(
                  mln_runtime_event_batch_view
                    .messages(source)
                    .reinterpret(dataSize)
                    .asSlice(offset, length),
                  length,
                )
                .decodeToString(),
            )
          }
        }
    )

