  fun writeOpenglContextDescriptor(arena: Arena, value: OpenglContextDescriptor): MemorySegment {
    val result = mln_opengl_context_descriptor.allocate(arena)
    mln_opengl_context_descriptor.size(result, mln_opengl_context_descriptor.sizeof().toInt())
    mln_opengl_context_descriptor.ownership(result, value.ownership.rawValue.toInt())
    when (val variant = value.data) {
      is OpenglContextDescriptorData.Wgl -> {
        mln_opengl_context_descriptor.platform(
          result,
          MapLibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_WGL(),
        )
        mln_opengl_context_descriptor_data
          .wgl(mln_opengl_context_descriptor.data(result))
          .copyFrom(GeneratedValues.writeWglContextDescriptor(arena, variant.value))
      }
      is OpenglContextDescriptorData.Egl -> {
        mln_opengl_context_descriptor.platform(
          result,
          MapLibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_EGL(),
        )
        mln_opengl_context_descriptor_data
          .egl(mln_opengl_context_descriptor.data(result))
          .copyFrom(GeneratedValues.writeEglContextDescriptor(arena, variant.value))
      }
      is OpenglContextDescriptorData.Webgl -> {
        mln_opengl_context_descriptor.platform(
          result,
          MapLibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_WEBGL(),
        )
        mln_opengl_context_descriptor_data
          .webgl(mln_opengl_context_descriptor.data(result))
          .copyFrom(GeneratedValues.writeWebglContextDescriptor(arena, variant.value))
      }
      is OpenglContextDescriptorData.Unknown ->
        throw IllegalArgumentException("unknown native union variants cannot be submitted")
    }
    return result
  }

  fun readOpenglContextDescriptor(source: MemorySegment): OpenglContextDescriptor =
    OpenglContextDescriptor(
      ownership = OpenglContextOwnership(mln_opengl_context_descriptor.ownership(source).toUInt()),
      data =
        when (mln_opengl_context_descriptor.platform(source)) {
          MapLibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_WGL() ->
            OpenglContextDescriptorData.Wgl(
              GeneratedValues.readWglContextDescriptor(
                mln_opengl_context_descriptor_data.wgl(mln_opengl_context_descriptor.data(source))
              )
            )
          MapLibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_EGL() ->
            OpenglContextDescriptorData.Egl(
              GeneratedValues.readEglContextDescriptor(
                mln_opengl_context_descriptor_data.egl(mln_opengl_context_descriptor.data(source))
              )
            )
          MapLibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_WEBGL() ->
