  fun writeRenderedQueryGeometry(arena: Arena, value: RenderedQueryGeometry): MemorySegment {
    val result = mln_rendered_query_geometry.allocate(arena)
    mln_rendered_query_geometry.size(result, mln_rendered_query_geometry.sizeof().toInt())
    when (val variant = value.data) {
      is RenderedQueryGeometryData.Point -> {
        mln_rendered_query_geometry.type(
          result,
          MapLibreNativeC.MLN_RENDERED_QUERY_GEOMETRY_TYPE_POINT(),
        )
        mln_rendered_query_geometry_data
          .point(mln_rendered_query_geometry.data(result))
          .copyFrom(GeneratedValues.writeScreenPoint(arena, variant.value))
      }
      is RenderedQueryGeometryData.Box -> {
        mln_rendered_query_geometry.type(
          result,
          MapLibreNativeC.MLN_RENDERED_QUERY_GEOMETRY_TYPE_BOX(),
        )
        mln_rendered_query_geometry_data
          .box(mln_rendered_query_geometry.data(result))
          .copyFrom(GeneratedValues.writeScreenBox(arena, variant.value))
      }
      is RenderedQueryGeometryData.LineString -> {
        mln_rendered_query_geometry.type(
          result,
          MapLibreNativeC.MLN_RENDERED_QUERY_GEOMETRY_TYPE_LINE_STRING(),
        )
        mln_rendered_query_geometry_data
          .line_string(mln_rendered_query_geometry.data(result))
          .copyFrom(GeneratedValues.writeScreenLineString(arena, variant.value))
      }
      is RenderedQueryGeometryData.Unknown ->
        throw IllegalArgumentException("unknown native union variants cannot be submitted")
    }
    return result
  }

  fun readRenderedQueryGeometry(source: MemorySegment): RenderedQueryGeometry =
    RenderedQueryGeometry(
      data =
        when (mln_rendered_query_geometry.type(source)) {
          MapLibreNativeC.MLN_RENDERED_QUERY_GEOMETRY_TYPE_POINT() ->
            RenderedQueryGeometryData.Point(
              GeneratedValues.readScreenPoint(
                mln_rendered_query_geometry_data.point(mln_rendered_query_geometry.data(source))
              )
            )
          MapLibreNativeC.MLN_RENDERED_QUERY_GEOMETRY_TYPE_BOX() ->
            RenderedQueryGeometryData.Box(
              GeneratedValues.readScreenBox(
                mln_rendered_query_geometry_data.box(mln_rendered_query_geometry.data(source))
              )
            )
          MapLibreNativeC.MLN_RENDERED_QUERY_GEOMETRY_TYPE_LINE_STRING() ->
            RenderedQueryGeometryData.LineString(
              GeneratedValues.readScreenLineString(
                mln_rendered_query_geometry_data.line_string(
                  mln_rendered_query_geometry.data(source)
                )
              )
            )
          else ->
            RenderedQueryGeometryData.Unknown(
              mln_rendered_query_geometry.type(source).toUInt(),
              mln_rendered_query_geometry.data(source).toArray(ValueLayout.JAVA_BYTE),
            )
        }
    )

