  fun writeResourceResponse(arena: Arena, value: ResourceResponse): MemorySegment {
    val result = mln_resource_response.allocate(arena)
    mln_resource_response.size(result, mln_resource_response.sizeof().toInt())
    mln_resource_response.has_modified(result, false)
    mln_resource_response.has_expires(result, false)
    mln_resource_response.has_retry_after(result, false)
    mln_resource_response.status(result, value.status.rawValue.toInt())
    mln_resource_response.error_reason(result, value.errorReason.rawValue.toInt())
    mln_resource_response.bytes(result, GeneratedValues.rawBytes(arena, value.bytes))
    mln_resource_response.byte_count(result, value.bytes.size.toLong())
    mln_resource_response.error_message(
      result,
      if (value.errorMessage == null) MemorySegment.NULL
      else GeneratedValues.cString(arena, value.errorMessage!!),
    )
    mln_resource_response.must_revalidate(result, value.mustRevalidate)
    if (value.modifiedUnixMs != null) {
      mln_resource_response.has_modified(result, true)
      mln_resource_response.modified_unix_ms(result, value.modifiedUnixMs!!)
    }
    if (value.expiresUnixMs != null) {
      mln_resource_response.has_expires(result, true)
      mln_resource_response.expires_unix_ms(result, value.expiresUnixMs!!)
    }
    mln_resource_response.etag(
      result,
      if (value.etag == null) MemorySegment.NULL else GeneratedValues.cString(arena, value.etag!!),
    )
    if (value.retryAfterUnixMs != null) {
      mln_resource_response.has_retry_after(result, true)
      mln_resource_response.retry_after_unix_ms(result, value.retryAfterUnixMs!!)
    }
    return result
  }

