          mln_resource_response.bytes(source),
          mln_resource_response.byte_count(source),
        ),
      errorMessage =
        if (mln_resource_response.error_message(source).address() == 0L) null
        else mln_resource_response.error_message(source).reinterpret(Long.MAX_VALUE).getString(0),
      mustRevalidate = mln_resource_response.must_revalidate(source),
      modifiedUnixMs =
        if (mln_resource_response.has_modified(source))
          mln_resource_response.modified_unix_ms(source)
        else null,
      expiresUnixMs =
        if (mln_resource_response.has_expires(source)) mln_resource_response.expires_unix_ms(source)
        else null,
      etag =
        if (mln_resource_response.etag(source).address() == 0L) null
        else mln_resource_response.etag(source).reinterpret(Long.MAX_VALUE).getString(0),
      retryAfterUnixMs =
        if (mln_resource_response.has_retry_after(source))
          mln_resource_response.retry_after_unix_ms(source)
        else null,
    )

