  fun rawBytes(arena: Arena, value: ByteArray): MemorySegment =
    arena.allocate(maxOf(1, value.size).toLong()).also {
      if (value.isNotEmpty()) it.copyFrom(MemorySegment.ofArray(value))
    }

  fun readRawBytes(source: MemorySegment, count: Long): ByteArray {
    require(count in 0..Int.MAX_VALUE.toLong())
    return if (count == 0L) byteArrayOf()
    else source.reinterpret(count).toArray(ValueLayout.JAVA_BYTE)
  }

  fun optionalBytesView(arena: Arena, value: ByteArray?): MemorySegment =
    if (value == null) mln_buffer_view.allocate(arena) else byteView(arena, value)

  fun optionalStringView(arena: Arena, value: String?): MemorySegment =
    optionalBytesView(arena, value?.encodeToByteArray())

  fun stringView(arena: Arena, value: String): MemorySegment =
    byteView(arena, value.encodeToByteArray())

  fun byteView(arena: Arena, value: ByteArray): MemorySegment =
    mln_buffer_view.allocate(arena).also {
      mln_buffer_view.data(it, rawBytes(arena, value))
      mln_buffer_view.size(it, value.size.toLong())
    }

  fun readBytes(source: MemorySegment): ByteArray {
    val count = mln_buffer_view.size(source)
    require(count in 0..Int.MAX_VALUE.toLong())
    return if (count == 0L) byteArrayOf()
    else mln_buffer_view.data(source).reinterpret(count).toArray(ValueLayout.JAVA_BYTE)
  }

  fun readString(source: MemorySegment): String = readBytes(source).decodeToString()

  fun cString(arena: Arena, value: String): MemorySegment {
    BindingStatus.requireArgument('\u0000' !in value) { "text contains an embedded NUL" }
    return rawBytes(arena, value.encodeToByteArray() + byteArrayOf(0))
  }
}

